INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1995073205175046189', 'Thời còn đi học cấp 2 ở quê, có một người anh họ đi làm xa tết mới về.', 'thoi-con-di-hoc-cap-2-o-que-co-mot-nguoi-anh-ho-di-lam-xa-tet-moi-ve', 'Thời còn đi học cấp 2 ở quê, có một người anh họ đi làm xa tết mới về. Anh hãy bảo tôi nhất định phải lên thành phố học rồi kiếm cơ hội làm giàu. "Mấy người như anh em mình sinh ra không có bệ đỡ, tiề…', 'Thời còn đi học cấp 2 ở quê, có một người anh họ đi làm xa tết mới về. Anh hãy bảo tôi nhất định phải lên thành phố học rồi kiếm cơ hội làm giàu.

"Mấy người như anh em mình sinh ra không có bệ đỡ, tiền bạc không có, mối quán hệ càng không. Thì tại sao không đặt ra những mục tiêu thật to như: viện trưởng, bác sĩ, luật sư đánh giá, hoặc ít nhất cũng là doanh nhân thành đạt.

Để ít nhất đạt được thì có cái mà sĩ với con cháu, còn không thì có cái mà tự hào với chính mình.

Mấy thứ đó người bình thường cố gắng cả đời có khi còn không có, nên chúng ta không làm được cũng chẳng ai cười chê; còn làm được thì trở thành huyền thoại."

Anh còn bảo tôi tuyệt đối không được ăn phận, có tiền thì hút 3 số, không tiền thì hút Thăng Long. Bởi ước mơ là miễn phí. 

Nhờ sự động viên của anh mà lớp trẻ bọn tôi đứa nào cũng xa quê, mà cũng nhờ đó mới có tiệc tân gia nhà chú 3, dì 6. 

Sau này anh cũng là người cho tôi vay 3 cây vàng để mở garage.

Trộm nghĩ đám thanh niên thời bọn tôi gọi theo kiểu tục tĩu ngoài quê thì đúng là trên răng dưới ***, cũng không biết dòng đời đưa đẩy thế nào mà lại có cơ ngơi sự nghiệp như bây giờ.

Hôm nay là 100 ngày mất của anh, mong anh yên nghỉ!', 'https://pbs.twimg.com/media/G6_sgbWbYAAaevM.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Thời còn đi học cấp 2 ở quê, có một người anh họ đi làm xa tết mới về.', 'Thời còn đi học cấp 2 ở quê, có một người anh họ đi làm xa tết mới về. Anh hãy bảo tôi nhất định phải lên thành phố học rồi kiếm cơ hội làm giàu. "Mấy người như', 'triết học', '2025-11-30T17:11:33+07:00', '2025-11-30T17:11:33+07:00')
