INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1945094932630315371', 'Hồi còn trẻ tôi cũng tránh né review những sai lầm', 'hoi-con-tre-toi-cung-tranh-ne-review-nhung-sai-lam', '@YogiBNB_ Bán hết r thì nghỉ x 1 thời gian năm sau quay lại chiến tiếp, dowtrend r b @PhamVan32175 Nghỉ thì chán bro ạ', 'Hồi còn trẻ tôi cũng tránh né review những sai lầm

