INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1944571796084433113', 'Hôm nay lướt thấy cái này nên chia sẻ một chút về Manifest', 'hom-nay-luot-thay-cai-nay-nen-chia-se-mot-chut-ve-manifest', 'Hôm nay lướt thấy cái này nên chia sẻ một chút về Manifest. Chúng ta thường nghĩ về Manifest như một kiểu ước nguyện, xin xỏ... nhưng thật ra đó là một trạng thái của niềm tin. Ta cảm nhận được sự thà…', 'Hôm nay lướt thấy cái này nên chia sẻ một chút về Manifest.

Chúng ta thường nghĩ về Manifest như một kiểu ước nguyện, xin xỏ... nhưng thật ra đó là một trạng thái của niềm tin. 

Ta cảm nhận được sự thành công, thấy và tin mình thành công. Khi tâm trí đạt được "alignment" với những hành động, ta có niềm tin những hành động đó sẽ đem lại kết quả mình xứng đáng. 

Đó là lúc manifest có hiệu lực. 

Bạn không thể vừa manifest kiếm 1 tỷ trong lúc không biết làm sao để kiếm được 1 tỷ; không thể vừa xin một điều ước vừa không chắc về nó. 

Bạn phải có mảnh đất, bạn đang cày cuốc và bạn tin vào vụ mùa bội thu. Không phải nằm gác tay lên trán và kỳ vọng sẽ thu hoạch. 

Manifest nên là thứ giúp bạn tin và hành động nhiều hơn.', 'https://pbs.twimg.com/media/GvyBvgQbYAAzvqs.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Hôm nay lướt thấy cái này nên chia sẻ một chút về Manifest', 'Hôm nay lướt thấy cái này nên chia sẻ một chút về Manifest. Chúng ta thường nghĩ về Manifest như một kiểu ước nguyện, xin xỏ... nhưng thật ra đó là một trạng th', 'triết học', '2025-07-14T08:36:59+07:00', '2025-07-14T08:36:59+07:00')
