INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1939297575661949224', 'Nhiều người nghĩ ủa tại sao mình phải sống vừa lòng thiên hạ, thích gì làm đó thì không được à', 'nhieu-nguoi-nghi-ua-tai-sao-minh-phai-song-vua-long-thien-ha-thich-gi', 'Nhiều người nghĩ ủa tại sao mình phải sống vừa lòng thiên hạ, thích gì làm đó thì không được à? Nhưng thích gì làm đó nó rất nguy hiểm, một số người khi đã quá quen việc nuông chiều cảm xúc sẽ dần trở…', 'Nhiều người nghĩ ủa tại sao mình phải sống vừa lòng thiên hạ, thích gì làm đó thì không được à?

Nhưng thích gì làm đó nó rất nguy hiểm, một số người khi đã quá quen việc nuông chiều cảm xúc sẽ dần trở nên biến thái như thế này. 

Thật sự những tên biến thái, ấu dâm... cũng là một kiểu bệnh, họ chỉ có thể đạt được cực khoái khi thực hiện hành vi đó với những đối tượng cụ thể. 

Ta có thể thông cảm về mặt tinh thần, nhưng nếu họ không có khả năng tự kiểm soát những ham muốn của mình thì ta buộc phải kiểm soát họ. 

Nên con người phải tập được thói quen kiểm soát những cái sở thích của mình, có nhiều thứ dù ta có muốn cũng bắt buộc phải nói không.

Đây cũng là điều mà tôi dạy con mình đầu tiên. 

Làm người phải biết nói "không" với những gì mình thích. 

Bằng không thì đến một lúc nào đó hậu quả sẽ rất khó lường.', 'https://pbs.twimg.com/media/GunDLTPXkAAjd4C.png', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'draft', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Nhiều người nghĩ ủa tại sao mình phải sống vừa lòng thiên hạ, thích gì', 'Nhiều người nghĩ ủa tại sao mình phải sống vừa lòng thiên hạ, thích gì làm đó thì không được à? Nhưng thích gì làm đó nó rất nguy hiểm, một số người khi đã quá ', 'triết học', '2025-06-29T19:19:07+07:00', '2025-06-29T19:19:07+07:00')
