INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1937893732608827601', 'Làm người phải biết kiềm chế bản ngã', 'lam-nguoi-phai-biet-kiem-che-ban-nga', 'Làm người phải biết kiềm chế bản ngã Hồi ông nội tôi còn sống có dạy rằng con người phải biết nói "không" với những gì mình mong muốn, vì đạo đức, vì lương tri, vì giá trị... bằng không thì người đó s…', 'Làm người phải biết kiềm chế bản ngã

Hồi ông nội tôi còn sống có dạy rằng con người phải biết nói "không" với những gì mình mong muốn, vì đạo đức, vì lương tri, vì giá trị... bằng không thì người đó sẽ không thể có một kết cục tốt đẹp.

Hồi đó tôi còn nhỏ, không biết cuộc sống còn có điều gì khác ngoài tiền bạc và quyền lực. Nhưng mãi đến sau này mới biết cái ham muốn của con người nó vượt quá cái giới hạn về đạo đức và nhân phẩm rất nhiều.

Trong chữ hán, chữ "Dục" tức là ham muốn ban đầu ghép từ bộ "Khiếm" tức là thiếu thốn, bộ "Cốc" tức là lương thực, và bộ "Tâm". Khiếm và Cốc đè lên bộ Tâm mang hình tượng cái tham của con người thường lớn hơn lý trí và tư duy về đạo đức.

Sau này người ta bỏ hẳn bộ Tâm đi, chỉ còn lại chữ Dục ghép giữa Khiếm và Cốc, tượng hình một người quỳ gối và cái miệng há rộng. Ý muốn nói khi đã tham lam thì mất đi nhân tính và phẩm hạnh.

Cho nên con người có thể vì lòng tham, vì khao khát một cái gì đó mà trở thành một kẻ ác độc và phạm phải tội lỗi.

Sau này tôi rất thấm điều ông nội dạy, rằng đôi khi đứng trước sự cám dỗ, trước thứ mình rất khao khát phải học được cách từ chối, đó không chỉ đơn thuần là một tiêu chuẩn đạo đức, mà còn là nhân cách của một con người.', 'https://pbs.twimg.com/media/GuTH_5_awAAsaXz.png', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Làm người phải biết kiềm chế bản ngã', 'Làm người phải biết kiềm chế bản ngã Hồi ông nội tôi còn sống có dạy rằng con người phải biết nói "không" với những gì mình mong muốn, vì đạo đức, vì lương tri,', 'triết học', '2025-06-25T22:20:44+07:00', '2025-06-25T22:20:44+07:00')
