INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1934602653499265374', 'Ngày mà tiền số được công nhận thì anh em có còn bitcoin để xài không', 'ngay-ma-tien-so-duoc-cong-nhan-thi-anh-em-co-con-bitcoin-de-xai-khong', 'Ngày mà tiền số được công nhận thì anh em có còn bitcoin để xài không? Tôi biết nhiều anh em mua $BTC thì khi mới có mấy trăm $ nhưng đến giờ cũng chẳng còn. Đa phần anh em còn giữ đều mua khoản 5-6k$…', 'Ngày mà tiền số được công nhận thì anh em có còn bitcoin để xài không?

Tôi biết nhiều anh em mua $BTC thì khi mới có mấy trăm $ nhưng đến giờ cũng chẳng còn.

Đa phần anh em còn giữ đều mua khoản 5-6k$ - mua lúc 2018 2019, chứ mua từ 2014 đa số bán khi lên 2k hết rồi.

