INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1932100203299102791', 'Trăng tròn tháng này nằm ở một chòm sao gây tranh cãi trong giới chiêm tinh và thiên văn, đó là Opiuchus', 'trang-tron-thang-nay-nam-o-mot-chom-sao-gay-tranh-cai-trong-gioi', 'Trăng tròn tháng này nằm ở một chòm sao gây tranh cãi trong giới chiêm tinh và thiên văn, đó là Opiuchus. Nhiều người từng cho rằng thiên văn đã khám phá ra cung hoàng đạo thứ 13, nhưng thực tế thì nó…', 'Trăng tròn tháng này nằm ở một chòm sao gây tranh cãi trong giới chiêm tinh và thiên văn, đó là Opiuchus.

Nhiều người từng cho rằng thiên văn đã khám phá ra cung hoàng đạo thứ 13, nhưng thực tế thì nó là chòm nằm chồng lên toàn bộ Nhân Mã và Bọ Cạp, vì vậy nó vốn dĩ không được tính là một cung trong thiên văn và chiêm tinh cổ đại chứ không phải do ngừơi xưa không thấy. 

Trong thiên văn Babylon, một chòm sao được gọi là Sitting God ("Thần Ngồi") dường như đã được xếp nằm trong khu vực chung mà sau này là chòm sao Xà Phu.

Những quan sát và ghi nhận Xà Phu trong thực tế có thể đã bắt nguồn từ chòm sao cổ đại của Babylon này, biểu tượng đại diện cho Nirah, một con rắn thần hình dạng người, đôi khi được miêu tả với một nửa trên là con người và nửa còn lại là con rắn, thường là ở phần chân.', 'https://pbs.twimg.com/media/GtAy4n9aUAAIBoj.jpg', 'Chiêm Tinh Nội Môn', '{"Chiêm Tinh Nội Môn"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Trăng tròn tháng này nằm ở một chòm sao gây tranh cãi trong giới chiêm', 'Trăng tròn tháng này nằm ở một chòm sao gây tranh cãi trong giới chiêm tinh và thiên văn, đó là Opiuchus. Nhiều người từng cho rằng thiên văn đã khám phá ra cun', 'chiêm tinh nội môn', '2025-06-09T22:39:19+07:00', '2025-06-09T22:39:19+07:00')
