INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1923276790178488359', 'Tại Sao Việt Nam Hôm Nay Có Nhiều Bò Đỏ', 'tai-sao-viet-nam-hom-nay-co-nhieu-bo-do', 'Tại Sao Việt Nam Hôm Nay Có Nhiều Bò Đỏ? Ngay từ thời điểm chúng ta, và lũ trẻ của chúng ta bước vào ngôi trường học công lập, điều đầu tiên ta học là " Tiên Học Lễ - Hậu Học Văn " Và cái quan trọng t…', 'Tại Sao Việt Nam Hôm Nay Có Nhiều Bò Đỏ?
Ngay từ thời điểm chúng ta, và lũ trẻ của chúng ta bước vào ngôi trường học công lập, điều đầu tiên ta học là " Tiên Học Lễ - Hậu Học Văn "

Và cái quan trọng thứ 2 là thuộc lòng 5 Điều Bác Dạy. Điều này dường như đã trở thành một sự hiển nhiên, mà không một con người Việt Nam nào thắc mắc, hay đặt câu hỏi? Tại Sao?
Chỉ có sự tham lam, ngu dốt của đám Cosa mới đủ khả năng đem cái nghịch lý này vào để mị dân, ngu dân, ngay từ khi chúng dân mới nhú, còn ngây thơ và đúng nghĩa một tờ giấy trắng.

Khi ta nhìn lại, ta sẽ thấy ngay sự mâu thuẫn giữa câu " Tiên Học Lễ " với câu " Yêu tổ quốc, Yêu đồng bào ". Học lễ là học yêu thương, lễ phép với những người cận kề mình nhất. Với những đứa trẻ thì chính là cha mẹ, gia đình. Hà cớ sau lại phải " yêu tổ quốc, yêu đồng bào " !!?? Bọn trẻ biết gì về tổ quốc, đồng bào mà phải yêu !!?? Hay nói trắng ra tổ quốc, đồng bào mà bọn trẻ hiểu ở đây chính là môi trường của trường học tụi nó, là Đội, là Đoàn, hay một sự liên hệ thâm sâu hơn là Đảng ? Chưa dừng ở đó, cả năm câu đều không có câu nào nói bọn trẻ phải yêu thương cha mẹ của tụi nó, chỉ cổ xúy tụi nhỏ phải này, phải nọ, phải kia - chứ không phải là chính chúng nó!

Vậy hóa ra, câu nói trên là dạy bọn trẻ phải yêu Đảng đầu tiên ư !? Nếu đúng vậy thì không khó hiểu khi lực lượng bò đỏ hiện nay càng lúc càng trẻ, khỏe, và ngu dốt đến vậy, khi mà chúng nó phải nhồi nhét cái sự dối trá đó ngay từ khi chỉ là tờ giấy trắng 😔', 'https://pbs.twimg.com/media/GrDaDF9XoAAj8mJ.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'draft', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Tại Sao Việt Nam Hôm Nay Có Nhiều Bò Đỏ', 'Tại Sao Việt Nam Hôm Nay Có Nhiều Bò Đỏ? Ngay từ thời điểm chúng ta, và lũ trẻ của chúng ta bước vào ngôi trường học công lập, điều đầu tiên ta học là " Tiên Họ', 'triết học', '2025-05-16T14:18:14+07:00', '2025-05-16T14:18:14+07:00')
