INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1916766880242557315', 'Elon Musk sắp rời khỏi Bộ DOGE với những sai lầm của mình', 'elon-musk-sap-roi-khoi-bo-doge-voi-nhung-sai-lam-cua-minh', '@YogiBNB_ sao ông này với Trump lại làm mọi thứ loạn hết cả lên thế nhỉ? Không thấy phương hướng nào luôn! @GrassLucky Chủ yếu để truyền thông mà', 'Elon Musk sắp rời khỏi Bộ DOGE với những sai lầm của mình

Kế hoạch giúp chính phủ Mỹ tiết kiệm 2000 tỷ ngân sách đã thất bại nặng nề. 

Những nhân viên bị sa thải không theo quy trình đã quay lại khiếu kiện khiến cho chính phủ tốn thêm tiền bồi thường. 

Bên cạnh đó việc sa thải nhầm nhân viên thử việc vốn được tuyển để thay thế nhân viên sắp về hưu cũng gây tranh cãi.

