INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1913593828336156927', 'Ở đời tôi kị nhất là mấy thánh hay lên mạng so sánh phương tây với phương đông với cái tư duy nước ngoài cái gì cũng hơn cũng giỏi', 'o-doi-toi-ki-nhat-la-may-thanh-hay-len-mang-so-sanh-phuong-tay-voi', '@YogiBNB_ Khi văn hoá phương đông là nhẫn thì bọn tự luyến phương tây càng thêm thượng đẳng :))) @laam73106996 Uhm', 'Ở đời tôi kị nhất là mấy thánh hay lên mạng so sánh phương tây với phương đông với cái tư duy nước ngoài cái gì cũng hơn cũng giỏi

Họ không nhìn được cái văn hóa, giáo dục của phương đông đã nuôi dưỡng được bản thân - ngừơi mà bây giờ cầu tiến rồi đem phương tây ra ca ngợi hết lời.

Đơn cử như nhiều người hay nói văn minh phương tây có sớm, như thuốc tây chẳng hạn.

Phương đông cũng có đông y, cũng là văn minh của phương đông. Tuy rằng tây y có thể hiện đại và coi như là bước tiến của nhân lọai, thì nên cầu tiến để phát triển chứ không phải tự nhục.

Sắp tới 30/4 lướt đâu cũng thấy bài tự nhục.

@YogiBNB_ Khi văn hoá phương đông là nhẫn thì bọn tự luyến phương tây càng thêm thượng đẳng :)))

@laam73106996 Uhm', 'https://pbs.twimg.com/media/Go5zcLtaUAAS2Ut.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Ở đời tôi kị nhất là mấy thánh hay lên mạng so sánh phương tây với phư', '@YogiBNB_ Khi văn hoá phương đông là nhẫn thì bọn tự luyến phương tây càng thêm thượng đẳng :))) @laam73106996 Uhm', 'triết học', '2025-04-19T21:01:36+07:00', '2025-04-19T21:01:36+07:00')
