INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1907709043763995012', 'Cái Trump muốn ở VN chẳng phải là giảm thuế đâu.', 'cai-trump-muon-o-vn-chang-phai-la-giam-thue-dau', 'Cái Trump muốn ở VN chẳng phải là giảm thuế đâu. Cái ổng muốn là VN cam kết nhập nhiều hàng Mỹ hơn từ đó tạo thêm công ăn việc làm cho người Mỹ. Lấy vd iphone đi. Giá ip15 promax ở Mỹ loanh quang đâu…', 'Cái Trump muốn ở VN chẳng phải là giảm thuế đâu.  Cái ổng muốn là VN cam kết nhập nhiều hàng Mỹ hơn từ đó tạo thêm công ăn việc làm cho người Mỹ.

Lấy vd iphone đi. Giá ip15 promax ở Mỹ loanh quang đâu đó $1,100. Giá ở VN hiện đang 28tr => vụ VN đánh thuế trung bình 90% là ko có cơ sở. Cái số 90% này là chênh lệch cán cân thương mại của VN và Mỹ thôi.

=> muốn giảm con số này xuống chỉ có nước VN nhập khẩu hàng Mỹ nhiều hơn. 

Giảm thuế cho hàng Mỹ khó mà khiến VN nhập nhiều hơn vì dân VN quen xài hơn TQ, Hàn, Nhật rồi. Ngay cả xe hơi Mỹ ở thị trường VN dù có giảm giá do hưởng chính sách giảm thuế thì cũng khó tăng doanh số nhiều do còn cạnh tranh với xe hơi lắp ráp trong nước nữa (cả thương hiệu VN lẫn nước ngoài).

Giờ chỉ có nước mở các ưu đãi cho doanh nghiệp Mỹ tới kinh doanh ở VN hoặc cam kết sử dụng các dịch vụ của công ty Mỹ để giảm cán cân thương mại rồi thông qua đó thương lượng giảm bớt thuế hàng VN bị đánh xuống. Nếu ko khả thi thì phảu đi tìm các quốc gia khác xuất khẩu hàng VN để bớt phụ thuộc Mỹ thôi.', '', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Cái Trump muốn ở VN chẳng phải là giảm thuế đâu.', 'Cái Trump muốn ở VN chẳng phải là giảm thuế đâu. Cái ổng muốn là VN cam kết nhập nhiều hàng Mỹ hơn từ đó tạo thêm công ăn việc làm cho người Mỹ. Lấy vd iphone đ', 'triết học', '2025-04-03T15:17:34+07:00', '2025-04-03T15:17:34+07:00')
