INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1907609062243782705', 'Tỷ lệ ủng hộ Tổng thống Donald Trump giảm xuống còn 43%, mức thấp nhất kể từ khi ông trở lại nắm quyền, theo m…', 'ty-le-ung-ho-tong-thong-donald-trump-giam-xuong-con-43-muc-thap-nhat', '@mm_marketmaker Muộn rồi cưng', 'Tỷ lệ ủng hộ Tổng thống Donald Trump giảm xuống còn 43%, mức thấp nhất kể từ khi ông trở lại nắm quyền, theo một cuộc thăm dò của Reuters/Ipsos. 

Người Mỹ đang mất thiện cảm với các chính sách thuế quan của ông và cách chính quyền xử lý thông tin về cuộc tấn công quân sự ở Yemen. 

Cuộc thăm dò kéo dài 3 ngày, kết thúc vào hôm qua, cho thấy mức độ hài lòng với hiệu suất của Trump giảm 2 điểm phần trăm so với cuộc thăm dò từ ngày 21-23/3, và thấp hơn 4 điểm so với mức 47% mà ông có được ngay sau khi nhậm chức vào ngày 20/1. 

Lưu ý đây chỉ là khảo sát nhanh và nhóm nhỏ ở Mỹ mới đây.

@mm_marketmaker Muộn rồi cưng', 'https://pbs.twimg.com/media/GnkwU3AbkAAFRnz.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'draft', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Tỷ lệ ủng hộ Tổng thống Donald Trump giảm xuống còn 43%, mức thấp nhất', '@mm_marketmaker Muộn rồi cưng', 'triết học', '2025-04-03T08:40:16+07:00', '2025-04-03T08:40:16+07:00')
