INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1900798307682898006', 'Ko phải chỉ @MEXC_Official mà vấn đề đóng băng tk user thì @okx cũng là 1 cái tên điển hình, bản thân m đã từn…', 'ko-phai-chi-mexc-official-ma-van-de-dong-bang-tk-user-thi-okx-cung-la', 'Ko phải chỉ @MEXC_Official mà vấn đề đóng băng tk user thì @okx cũng là 1 cái tên điển hình, bản thân m đã từng bị, đang yên đang lành đóng băng tk xong bắt KYC lại nên m yêu cầu mở khoá để rút về rồi…', 'Ko phải chỉ @MEXC_Official mà vấn đề đóng băng tk user thì @okx cũng là 1 cái tên điển hình, bản thân m đã từng bị, đang yên đang lành đóng băng tk xong bắt KYC lại nên m yêu cầu mở khoá để rút về rồi bỏ luôn. Nhưng đa số m thấy mng hay bị như bạn này, sàn ko cung cấp lý do mà chỉ bảo "đợi". Bọn m đi đánh giải bị tính sai pnl cũng bảo "đợi", đến tận lúc kết thúc giải ko làm j đc nữa rồi mới xin lỗi cho qua. Hết!

Maf mấy cái giải bên #OKx mng cũng đừng tham gia làm j cho mệt, ko minh bạch đâu. Có team bị bóp pnl như team m, cũng có team đc bơm pnl như team @LuckyStudent02, ít chẳng nói chứ bơm căng đét cả chục nghìn % lên hẳn top2 thì mng leo rank bh mới lại. Vô tình hay cố ý chẳng biết, nhưng giải nào cũng lỗi ai mà ưng cho đc. @Bybit_Official tuy hay lấy risk control ra quịt thưởng user với hiển thị roi đánh lừa user nhưng chí ít ko bias trắng trợn như vậy.

Còn case b @jvevermind_vbc nếu ai chơi lâu bên #mexc chắc cũng ko lạ, thậm chí lúc biến động, lệnh đúng xu hướng thì sàn tự gỡ, tự cắt, còn lệnh sai xu hướng thì lại ko cho ngta out, ai ko bình tĩnh xử lý thì chỉ có ngồi nhìn tài khoản cháy.

M đã từng bị, còn ngồi quay video cả quá trình m xử lý lệnh thể hiện rõ từng cái sai của sàn ntn. Khi đưa video ra, mấy bạn BD còn công nhận đây là lỗi của sàn, khuyên m đi khiếu nại. M ko khiếu nại nhưng tự @MEXCVietnam chủ động inb muốn giải quyết vấn đề cho m. Tuy nhiên, vẫn chỉ là bảo mail cung cấp bằng chứng, rồi đến cuối cùng thì tiền mất vẫn ko lấy lại đc 🫠

Gặp vấn đề thì nên nói ra, thậm chí còn phải hô to dõng dạc, nhưng ko lấy lại đc tiền thì mng cũng đừng quá bất ngờ. Nhiều khi đó là tính năng chứ ko phải là lỗi như m nghĩ đâu.

#VanMei', '', 'Triết Học & Tỉnh Thức', '{"OKx","mexc","VanMei"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Ko phải chỉ @MEXC_Official mà vấn đề đóng băng tk user thì @okx cũng l', 'Ko phải chỉ @MEXC_Official mà vấn đề đóng băng tk user thì @okx cũng là 1 cái tên điển hình, bản thân m đã từng bị, đang yên đang lành đóng băng tk xong bắt KYC', 'okx, mexc, vanmei', '2025-03-15T13:36:46+07:00', '2025-03-15T13:36:46+07:00')
