INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1897277524805300347', 'Anh em follow tôi có ai theo trường phái long/short không', 'anh-em-follow-toi-co-ai-theo-truong-phai-long-short-khong', '@YogiBNB_ Vote 1 vote bác Bụt ơi @NguynThuTh76212 Hold spot thì phải giỏi về cơ bản, đánh long/short thì phải giỏi ptkt, tin tức. Cơ bản đều cần phải rèn luyện tâm lý', 'Anh em follow tôi có ai theo trường phái long/short không?

Vừa có dịp gặp vài anh em trader, thấy đa số đều khá thoải mái. Lên thì đánh lên, xuống đánh xuống.

Giàu thì không giàu nhưng đủ để tự chu cấp cho cuộc sống và chẳng phải lo gì đến layoff.

Đương nhiên để đạt được cái tầm này cũng coi như nếm mật nằm gai đủ nhiều rồi, nhưng thật ra cũng là một nghề rất thú vị.

Ngồi quan sát thị trường và học cách điềm tĩnh nơi mỗi người đấu đá nhau qua màn hình cũng là một điều thú vị.

Đợt này vừa test vài chiến thuật trade khá phù hợp cho crypto, nếu anh em thích thì tôi lâu lâu đưa vài lệnh cho anh em test.

@YogiBNB_ Vote 1 vote bác Bụt ơi

@NguynThuTh76212 Hold spot thì phải giỏi về cơ bản, đánh long/short thì phải giỏi ptkt, tin tức. Cơ bản đều cần phải rèn luyện tâm lý.', 'https://pbs.twimg.com/media/GlR71-LbQAAKF5Y.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Anh em follow tôi có ai theo trường phái long/short không', '@YogiBNB_ Vote 1 vote bác Bụt ơi @NguynThuTh76212 Hold spot thì phải giỏi về cơ bản, đánh long/short thì phải giỏi ptkt, tin tức. Cơ bản đều cần phải rèn luyện ', 'triết học', '2025-03-05T20:26:26+07:00', '2025-03-05T20:26:26+07:00')
