INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1894348638794781060', 'Kế hoạch giải thể USAID đang được tiến hành, bỏ ngỏ hằng trăm dự án clear tàn dư chiến tranh trên thế giới', 'ke-hoach-giai-the-usaid-dang-duoc-tien-hanh-bo-ngo-hang-tram-du-an', '@YogiBNB_ USAID cái ổ rửa tiền cho bọn quan quyền Mỹ, bơm tiền cho khủng bố để gây bất ổn chính trị vùng trung đông. Cái mã USAID này chỉ đc lúc đầu khi dựng lên, sau này lòi mặt chuột lũ dòi bọ tham…', 'Kế hoạch giải thể USAID đang được tiến hành, bỏ ngỏ hằng trăm dự án clear tàn dư chiến tranh trên thế giới.

Mọi thứ đều có 2 mặt, USAID từng tài trợ những chương trình bảo vệ nguồn nước sạch ở châu Phi, chương trình sốt rét, dự án điện tái tạo ở VN và cả những dự án xóa chất độc màu da cam.

"Việc chấm dứt USAID sẽ phá hủy những thành quả khó khăn lắm mới đạt được trong cuộc chiến chống đói nghèo và khủng hoảng nhân đạo, và gây ra tác hại lâu dài, không thể khắc phục được”, Chủ tịch Oxfam America Abby Maxman cho biết trong một tuyên bố.

Elon Musk được cho là kẻ độc tài đã bằng một cách nào đó có quyền lực lớn và được sự ủng hộ trực tiếp từ tổng thống mà bỏ qua quốc hội.

@YogiBNB_ USAID cái ổ rửa tiền cho bọn quan quyền Mỹ, bơm tiền cho khủng bố để gây bất ổn chính trị vùng trung đông. 
Cái mã USAID này chỉ đc lúc đầu khi dựng lên, sau này lòi mặt chuột lũ dòi bọ tham nhũng. Tiền tài trợ cả trăm triệu, nhưng đến tay có chục ngàn🤣

@Jkjj446 Tham nhũng là có, bộ phận nào cũng thế thôi, cần thay đổi và chống tham nhũng chứ không phải dẹp hẳn.
Cá nhân tôi có tham gia vào một số tổ chức xã hội nhận viện trợ từ USAID đang phải đi tìm nguồn viện trợ khác.', 'https://pbs.twimg.com/media/GkoUBzAbkAA-4xw.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'draft', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Kế hoạch giải thể USAID đang được tiến hành, bỏ ngỏ hằng trăm dự án cl', '@YogiBNB_ USAID cái ổ rửa tiền cho bọn quan quyền Mỹ, bơm tiền cho khủng bố để gây bất ổn chính trị vùng trung đông. Cái mã USAID này chỉ đc lúc đầu khi dựng lê', 'triết học', '2025-02-25T18:28:05+07:00', '2025-02-25T18:28:05+07:00')
