INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1891705919295324556', 'Binance mở vote để list $PI', 'binance-mo-vote-de-list-pi', 'Ở diễn biến khác thì nghe nói #Bybit xin duyệt KYB thất bại nên mới lên tus cay đắng với $PI chứ không phải không list $PI. Dĩ nhiên nếu không định niêm yết thì đã không nộp đơn KYB', '#Binance mở vote để list $PI

Tỷ lệ hiện tại là 84% gần như ăn chắc rồi. 

Trong khi Bybit từ chối list $PI vì lo sợ mô hình ponzi này ảnh hưởng đến uy tín, #OKX không cho người dùng nội địa Trung dept lên sàn.

Ở một góc nhìn khác thì mod $PI nói rằng #Binance còn đang trong quá trình KYB để được list, ra voting chỉ để kiếm thêm user Kyc và hold 5$ trong ví thôi.

Đại khái $PI áp dụng mô hình KYC cho người dùng cá nhân, sàn, doanh nghiệp thì phải KYB để xác nhận tư cách doanh nghiệp. 

#OKX #Bitget #Mexc #Gate đã thông qua xác minh doanh nghiệp để được listing $PI.

Cơ bản là Pi thủ cũng có lý, sàn cần $Pi chứ Pi không cần sàn để sống vì không có sàn thì nó cũng có market place rồi. 

Anh em nghĩ liệu #Binance có list $Pi không?

Ở diễn biến khác thì nghe nói #Bybit xin duyệt KYB thất bại nên mới lên tus cay đắng với $PI chứ không phải không list $PI. Dĩ nhiên nếu không định niêm yết thì đã không nộp đơn KYB👍', 'https://pbs.twimg.com/media/GkCsbQtaAAEFQG9.jpg', 'Triết Học & Tỉnh Thức', '{"Binance","OKX","PI"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Binance mở vote để list $PI', 'Ở diễn biến khác thì nghe nói #Bybit xin duyệt KYB thất bại nên mới lên tus cay đắng với $PI chứ không phải không list $PI. Dĩ nhiên nếu không định niêm yết thì', 'binance, okx, pi', '2025-02-18T11:26:52+07:00', '2025-02-18T11:26:52+07:00')
