INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1880200040536588293', 'Đã uống 2 ly mà chưa tới nơi, đoạn đường bây giờ toàn x2 thời gian.', 'da-uong-2-ly-ma-chua-toi-noi-doan-duong-bay-gio-toan-x2-thoi-gian', '@mm_marketmaker Thế em không biết rồi, kẹt xe là bước đầu tiên để thu phí xe cộ đi vào vùng mật độ giao thông cao đấy! VN văn minh tiến bộ như New York mà kk', 'Đã uống 2 ly mà chưa tới nơi, đoạn đường bây giờ toàn x2 thời gian. Thiệt hại kinh tế là rất lớn. Ngày xưa thấy Indonesia, Malaysia, Thái Lan than vụ kẹt xe gây thiệt hại kinh tế tỉ đô. Giờ mới được trải nghiệm. 

Lấy ví dụ bình thường đi làm 1 tiếng thì giờ người ta đi làm 2 tiếng, 2 chiều đi về là 4 tiếng. 4 tiếng đó nếu ở nhà máy thì sản xuất được bao nhiêu sản phẩm? Nếu tắt đường cao tốc thì hàng hoá trái cây xuất khẩu chậm=> hư hỏng thiệt hại là bao nhiêu? Trễ chuyến bay không thể kí hợp đồng là bao nhiêu…

@mm_marketmaker Thế em không biết rồi, kẹt xe là bước đầu tiên để thu phí xe cộ đi vào vùng mật độ giao thông cao đấy! VN văn minh tiến bộ như New York mà kk', 'https://pbs.twimg.com/amplify_video_thumb/1880199933422366724/img/FyhVSdvpL0BiVzjS.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'draft', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Đã uống 2 ly mà chưa tới nơi, đoạn đường bây giờ toàn x2 thời gian.', '@mm_marketmaker Thế em không biết rồi, kẹt xe là bước đầu tiên để thu phí xe cộ đi vào vùng mật độ giao thông cao đấy! VN văn minh tiến bộ như New York mà kk', 'triết học', '2025-01-17T17:26:36+07:00', '2025-01-17T17:26:36+07:00')
