INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1879338658513498256', 'Biết là anh em khuyên nhau giữ hàng qua giai đoạn rung lắc là thiện ý', 'biet-la-anh-em-khuyen-nhau-giu-hang-qua-giai-doan-rung-lac-la-thien-y', '@mm_marketmaker Kk, kinh nghiệm xưa giờ nếu mình khuyên ai chốt mà họ chốt thì nó bay, ngược lại nếu họ ko chốt thì nó dump', 'Biết là anh em khuyên nhau giữ hàng qua giai đoạn rung lắc là thiện ý. 

Nhưng đáng nói ở chỗ người khuyên không biết người nghe cầm hàng gì và ngược lại. Chưa kể người khuyên đang cầm hàng xịn chỉ bị mất lãi chứ chưa chắc lỗ, trong khi đó người nghe đang bị lỗ nặng mà còn cầm hàng “yếu” nhưng lại ko biết. Thế rồi một bên thiện ý khuyên một bên tích cực mù quáng. Bởi anh em nên tìm những ai cầm hàng giống mình mà nghe lời khuyên để có thể củng cố thêm lòng tin tích cực (độc hại) chẳng hạn.

Giống cuộc sống vậy, ko có tam quan tương hợp thì sao hợp tác kinh doanh hoặc yêu nhau được. 

Thật ko thể tin được. Mình đã bán Toshi không lâu trước đó 😂 lại là huyền thoại bán đáy

@mm_marketmaker Kk, kinh nghiệm xưa giờ nếu mình khuyên ai chốt mà họ chốt thì nó bay, ngược lại nếu họ ko chốt thì nó dump', 'https://pbs.twimg.com/media/GhTAi5YbwAAbYKG.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Biết là anh em khuyên nhau giữ hàng qua giai đoạn rung lắc là thiện ý', '@mm_marketmaker Kk, kinh nghiệm xưa giờ nếu mình khuyên ai chốt mà họ chốt thì nó bay, ngược lại nếu họ ko chốt thì nó dump', 'triết học', '2025-01-15T08:23:47+07:00', '2025-01-15T08:23:47+07:00')
