INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1877301900082819085', '- Học là để chiến thắng bản thân mình trước đã, phải biết mình đang ở chỗ nào của thị trường và mình đã đủ mạnh chưa.', 'hoc-la-de-chien-thang-ban-than-minh-truoc-da-phai-biet-minh-dang-o', '- Học là để chiến thắng bản thân mình trước đã, phải biết mình đang ở chỗ nào của thị trường và mình đã đủ mạnh chưa. Đi học sẽ biết được cái này nhanh nhất. -> ae bước vào smartmoney phát hiện ra ché…', '- Học là để chiến thắng bản thân mình trước đã, phải biết mình đang ở chỗ nào của thị trường và mình đã đủ mạnh chưa. Đi học sẽ biết được cái này nhanh nhất. -> ae bước vào smartmoney phát hiện ra chén thánh kiếm tiền easy sẽ nằm ở đoạn này.

- Sau khi thấy rõ mình đang ở đâu, và chiến thắng bản thân, quản lý kiến thức và cảm xúc tốt, quản lý tiền của bản thân tốt, phù hợp với chính cá nhân mình. Lúc đó mới đi đấm nhau với thị trường. -> ae mà bị cháy vài lần thường họ sẽ nghiệm ra cái này.

- Nếu đấm nhau với thị trường bị thua thì trả lại 2 lý do: mình chưa thực sự ngon; hoặc là bị xui. Nếu dính vào case "xui" thì mới nói đến chuyện trăm bó đuốc bắt con ếch bự. Còn kiến thức chưa ngon thì trước sau gì cũng bị thị trường luộc lại. -> ae mà trade chuyên nghiệp với profit đều đều nhẹ nhàng hoặc quản lý quỹ sẽ cảm nhận được case này.

=> Người đi dạy chưa chắc là người đấm nhau giỏi nhưng thường họ phải là người đấm nhau tốt, hiểu nhiều phương pháp đấm nhau. Người đi dạy chưa chắc họ thắng ở giải đấu triệu $ (ý là porfolio triệu $) nhưng với porf k$ lại rất nhẹ nhàng. Quá trình họ dạy rất có thể họ sẽ phát hiện ra các tài năng có thể đấm giải triệu $ hoặc nhiều hơn nữa, tài năng đó hoàn toàn tiềm năng để đi đấm thuê chứ không bỏ lãng phí được.

Việc các khóa học mở ra để lùa gà hoặc kiếm tiền làm giàu từ học viên cũng có nhiều, gọi là thật giả lẫn lộn. Ae qua nay thấy cay cú về việc "bán khóa học", lời khuyên của mình là việc học là cần, chỉ là chọn cái phù hợp với mỗi người thôi, người thích trade ngắn hạn thì học TA, người thích trade dài hạn thì kết hợp học FA nữa, người thích kiếm trend thì phải tham gia các hội thảo xu hướng của các idol build với phí đắt đỏ, người làm dự án thì phải học về logic kinh tế dự án,... đều vẫn phải chọn cái phù hợp.', '', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, '- Học là để chiến thắng bản thân mình trước đã, phải biết mình đang ở ', '- Học là để chiến thắng bản thân mình trước đã, phải biết mình đang ở chỗ nào của thị trường và mình đã đủ mạnh chưa. Đi học sẽ biết được cái này nhanh nhất. ->', 'triết học', '2025-01-09T17:30:26+07:00', '2025-01-09T17:30:26+07:00')
