INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1857064987094618487', 'Sao Thổ thuận hành đem công lý quay trở lại', 'sao-tho-thuan-hanh-dem-cong-ly-quay-tro-lai', 'Sao Thổ thuận hành đem công lý quay trở lại Sao Thổ đang tọa lạc tại chòm sao do La Hầu cai trị, La Hầu và Kế Đô được mệnh danh là "outcaster" - những kẻ sống ngoài rìa xã hội. Theo một cách nào đó th…', 'Sao Thổ thuận hành đem công lý quay trở lại

Sao Thổ đang tọa lạc tại chòm sao do La Hầu cai trị, La Hầu và Kế Đô được mệnh danh là "outcaster" - những kẻ sống ngoài rìa xã hội. 

Theo một cách nào đó thì động vật, chúng không có tiếng nói, mạng sống không được bảo vệ, không biết kêu oan... 

Đây cũng là một trong những động lực khiến câu chuyện con sóc $PNUT hay chú khỉ $JORGIE bỗng dưng được đưa lên truyền thông để đòi lại sự công bằng cho động vật hoang dã.

Chúng ta không lý giải mọi thứ theo cách gọt chân vừa giày, nhưng anh em có thể tự hỏi vì sao ngược đãi thú cưng, động vật có thể từng xảy ra trong thầm lặng, bỗng dưng một ngày truyền thông lại phản ứng mãnh liệt như vậy?

Tương tự như tháng 5/2020 trong vụ cảnh sát đàn áp và gây sát thương lên George Floyd - khơi mào cho cuộc chiến BLM bùng nổ khắp nước Mỹ - Sao Hỏa cũng nằm ở chòm sao Satabisha, Sao Thổ nghịch hành ở chòm sao Uttarashadha cung Ma Kết. Đều nói lên một cuộc cách mạng của những kẻ dị biệt, yếu thế.

Vì vậy, khi quá cảnh này diễn ra, không khó hiểu khi công lý được thực thi cho những ngừơi thấp kém.', 'https://pbs.twimg.com/media/GcWew1VXYAAEVxt.jpg', 'Chu Kỳ Vũ Trụ & Thời Cuộc', '{"Hỏa Tinh","Thổ Tinh","La Hầu","Kế Đô","PNUT","JORGIE"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Sao Thổ thuận hành đem công lý quay trở lại', 'Sao Thổ thuận hành đem công lý quay trở lại Sao Thổ đang tọa lạc tại chòm sao do La Hầu cai trị, La Hầu và Kế Đô được mệnh danh là "outcaster" - những kẻ sống n', 'hỏa tinh, thổ tinh, la hầu, kế đô, pnut, jorgie', '2024-11-14T21:16:10+07:00', '2024-11-14T21:16:10+07:00')
