INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1856623925020786835', 'Ngân quỹ của chính phủ Bhutan đã có 1 tỷ đô $BTC', 'ngan-quy-cua-chinh-phu-bhutan-da-co-1-ty-do-btc', 'Ngân quỹ của chính phủ Bhutan đã có 1 tỷ đô $BTC Bhutan và El Salvador là 2 quốc gia lưu trữ nhiều Crypto nhất trên thế giới (đương nhiên là không tính lượng crypto không công khai của chính phủ Mỹ và…', 'Ngân quỹ của chính phủ Bhutan đã có 1 tỷ đô $BTC 

Bhutan và El Salvador là 2 quốc gia lưu trữ nhiều Crypto nhất trên thế giới (đương nhiên là không tính lượng crypto không công khai của chính phủ Mỹ và Trung Quốc).

Với một quốc gia có nền kinh tế trị giá chưa đến 3 tỷ đô, thì 1 tỷ đô là 1/3 tổng ngân khố quốc gia. 

Vua Jigme Khesar Namgyal Wangchuck đã đề xuất xây dựng một "Thành phố chánh niệm Gelephu" (GMC) ở biên giới Ấn Độ để cung cấp không gian cho các doanh nghiệp tài chính, du lịch, năng lượng xanh, công nghệ, y tế, nông nghiệp, hàng không, hậu cần, giáo dục và tâm linh.

GMC là dự án nằm trong một khu vực hành chính đặc biệt với các quy tắc và luật lệ riêng biệt nhằm mục đích trở thành hành lang kinh tế nối Nam Á với Đông Nam Á.', 'https://pbs.twimg.com/media/GcQNnvHbkAAxJlg.jpg', 'Triết Học & Tỉnh Thức', '{"BTC"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Ngân quỹ của chính phủ Bhutan đã có 1 tỷ đô $BTC', 'Ngân quỹ của chính phủ Bhutan đã có 1 tỷ đô $BTC Bhutan và El Salvador là 2 quốc gia lưu trữ nhiều Crypto nhất trên thế giới (đương nhiên là không tính lượng cr', 'btc', '2024-11-13T16:03:32+07:00', '2024-11-13T16:03:32+07:00')
