INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1856609455821205622', 'Hồi tháng 3 mình có chuyển 1 phần Doge qua Pepe, nếu xét vị thế chuyển qua thì hơi thiệt hơn so với việc không chuyển.', 'hoi-thang-3-minh-co-chuyen-1-phan-doge-qua-pepe-neu-xet-vi-the-chuyen', 'Hồi tháng 3 mình có chuyển 1 phần Doge qua Pepe, nếu xét vị thế chuyển qua thì hơi thiệt hơn so với việc không chuyển. Nhưng do hiểu rằng mỗi mùa mới sẽ có những kèo meme mới xuất hiện nên vẫn phải ch…', 'Hồi tháng 3 mình có chuyển 1 phần Doge qua Pepe, nếu xét vị thế chuyển qua thì hơi thiệt hơn so với việc không chuyển. Nhưng do hiểu rằng mỗi mùa mới sẽ có những kèo meme mới xuất hiện nên vẫn phải chuyển để có động lực follow văn hóa của mùa meme mới.

Chơi meme trend mới mình thấy vừa dễ, vừa khó nhưng nếu không fulltime với nó thì khó mà ăn được. 

-> Muốn nói rằng ae muốn earn nhanh thì phải cày, ko cày thì vẫn phải cẩn thận trước sự cám dỗ của meme vì meme không dễ như ae tưởng.', '', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'draft', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Hồi tháng 3 mình có chuyển 1 phần Doge qua Pepe, nếu xét vị thế chuyển', 'Hồi tháng 3 mình có chuyển 1 phần Doge qua Pepe, nếu xét vị thế chuyển qua thì hơi thiệt hơn so với việc không chuyển. Nhưng do hiểu rằng mỗi mùa mới sẽ có nhữn', 'triết học', '2024-11-13T15:06:03+07:00', '2024-11-13T15:06:03+07:00')
