INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1856339105875148813', 'Một văn bản tên là Kāma Gītā trong bộ sử thi Mahabharata ghi lại cuộc đối thoại với Tham Ái như sau', 'mot-van-ban-ten-la-kama-gita-trong-bo-su-thi-mahabharata-ghi-lai-cuoc', 'Một văn bản tên là Kāma Gītā trong bộ sử thi Mahabharata ghi lại cuộc đối thoại với Tham Ái như sau: Các người muốn chiến thắng dục vọng, nhưng bản thân cái muốn đó cũng do dục vọng thúc đẩy. Ta (tham…', 'Một văn bản tên là Kāma Gītā trong bộ sử thi Mahabharata ghi lại cuộc đối thoại với Tham Ái như sau:

Các người muốn chiến thắng dục vọng, nhưng bản thân cái muốn đó cũng do dục vọng thúc đẩy. Ta (tham ái) đứng đằng sau những mong muốn giác ngộ!

Thái Tử Siddharta sau 6 năm khổ hạnh ép xác đã nhận ra rằng nỗ lực để chứng ngộ không đem lại một kết quả gì cả. Cuối cùng ông đã buông bỏ các tham vọng, sử dụng thực phẩm và liên tục thiền định trong 49 ngày và trở thành Buddha. 

Trong Kinh Tạng Nguyên Thủy có câu: Chánh Pháp còn phải bỏ huống gì là phi pháp?
Trong Thiền Tông có công án: gặp Phật giết Phật, gặp Ma giết Ma. 

Triết lý của Phật Giáo rất gần với Hindu Giáo và thậm chí từng có giai đoạn mà các tu sĩ Phật Giáo và tu sĩ Hindu Giáo cùng chia sẻ một ngôi đền ở bang Maharastra vào thế kỷ thứ 7.

Bức Tượng Thái Tử Siddharta trong 6 năm khổ hạnh được trưng bày ở bảo tàng Pakistan.

#Vedicastrology #votive', 'https://pbs.twimg.com/media/GcMKk_zasAAFU2n.jpg', 'Chu Kỳ Vũ Trụ & Thời Cuộc', '{"Vedicastrology","votive"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Một văn bản tên là Kāma Gītā trong bộ sử thi Mahabharata ghi lại cuộc ', 'Một văn bản tên là Kāma Gītā trong bộ sử thi Mahabharata ghi lại cuộc đối thoại với Tham Ái như sau: Các người muốn chiến thắng dục vọng, nhưng bản thân cái muố', 'vedicastrology, votive', '2024-11-12T21:11:46+07:00', '2024-11-12T21:11:46+07:00')
