INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1822611840050037026', 'Anh em follow tôi từ đầu đều biết rằng chiêm tinh đã được sử dụng để dự đoán trước', 'anh-em-follow-toi-tu-dau-deu-biet-rang-chiem-tinh-da-duoc-su-dung-de', 'Anh em follow tôi từ đầu đều biết rằng chiêm tinh đã được sử dụng để dự đoán trước: - nhịp tăng của thị trường sau tháng 1 - nhịp giảm giá vào tháng 5 - dự đoán thành công sự quay đầu của Yên Nhật - s…', 'Anh em follow tôi từ đầu đều biết rằng chiêm tinh đã được sử dụng để dự đoán trước:

- nhịp tăng của thị trường sau tháng 1

- nhịp giảm giá vào tháng 5

- dự đoán thành công sự quay đầu của Yên Nhật

- sự bất ổn và bạo động ở khu vực Trung Đông cũng như sự suy tàn của Bangladesh do chiến tranh tôn giáo

- dự đoán Biden sẽ sớm rút lui

Thậm chí đã dự trước cú điều chỉnh ngày 5/8 (dù cá nhân tôi đã hơi lạc quan khi nghĩ nó không tạo đáy mới).

Tôi đa phần phân tích vĩ mô và $BTC, đương nhiên tùy theo tình hình của thị trường thì đôi khi tôi không thể public 100% nhận định nếu nó đi ngược số đông quá nhiều.

Nhưng hiện tại tôi vẫn dự phóng nhịp tăng vào tháng 10 và siêu chu kỳ cho crypto vào 2025.

Anh em tin thì hưởng thôi.', 'https://pbs.twimg.com/media/GUs3y8YboAAtzKy.jpg', 'Chu Kỳ Vũ Trụ & Thời Cuộc', '{"BTC"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Anh em follow tôi từ đầu đều biết rằng chiêm tinh đã được sử dụng để d', 'Anh em follow tôi từ đầu đều biết rằng chiêm tinh đã được sử dụng để dự đoán trước: - nhịp tăng của thị trường sau tháng 1 - nhịp giảm giá vào tháng 5 - dự đoán', 'btc', '2024-08-11T19:31:39+07:00', '2024-08-11T19:31:39+07:00')
