INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1792565790778220802', '2021 sau khi chốt lãi và tạm rời khỏi thị trường, tôi đã có một chuyến đi lên vùng cao, trao tặng áo ấm cho 20 trường tiểu học', '2021-sau-khi-chot-lai-va-tam-roi-khoi-thi-truong-toi-da-co-mot-chuyen', '2021 sau khi chốt lãi và tạm rời khỏi thị trường, tôi đã có một chuyến đi lên vùng cao, trao tặng áo ấm cho 20 trường tiểu học. Đó là một chuyến đi đã thay đổi tôi thành một người khác. Không phải ngẫ…', '2021 sau khi chốt lãi và tạm rời khỏi thị trường, tôi đã có một chuyến đi lên vùng cao, trao tặng áo ấm cho 20 trường tiểu học.

Đó là một chuyến đi đã thay đổi tôi thành một người khác. 

Không phải ngẫu nhiên mà có người chọn cách tu bằng khất thực và đi bộ. 

Thay vì ngồi thiền, cầu nguyện, đi cũng là một cách để con người có cơ hội bước ra khỏi vòng xoáy mặc định của cuộc sống.

Trong Kinh Thánh ghi lại những câu chuyện các môn đồ đi khắp xứ Jerusalem để truyền giáo; Kinh Phật cũng kể về Đức Phật dành 45 năm để đi khắp xứ Ấn Độ giảng pháp.

Những bậc tu hành thật sự không ai khép cửa lại và tìm sự giải thoát cho riêng mình. 

Anh em ở đây có thể có đạo, có thể không. Nhưng con đường để phát triển vẫn là nên đi nhiều nơi và quan sát cuộc sống. 

2025 anh em ở đây ít cũng có vài tỷ, nhiều thì vài chục, hãy dành ra một ít để thực hiện những chuyến đi dài ngày và ý nghĩa.

Anh em sẽ tìm thấy được những mục tiêu kế tiếp cho bản thân mình.', 'https://pbs.twimg.com/media/GOB1xR-bcAEEej7.jpg', 'Triết Học & Tỉnh Thức', '{"Triết Học"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, '2021 sau khi chốt lãi và tạm rời khỏi thị trường, tôi đã có một chuyến', '2021 sau khi chốt lãi và tạm rời khỏi thị trường, tôi đã có một chuyến đi lên vùng cao, trao tặng áo ấm cho 20 trường tiểu học. Đó là một chuyến đi đã thay đổi ', 'triết học', '2024-05-20T21:39:23+07:00', '2024-05-20T21:39:23+07:00')
