INSERT INTO public.posts (id, title, slug, excerpt, content, cover_image, category, tags, status, author_name, author_role, read_time, views_count, featured, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES ('tw-1784126597693636835', 'Chiêm nghiệm bản đồ sao của Mỹ trong những đợt khủng hoảng kinh tế vừa qua', 'chiem-nghiem-ban-do-sao-cua-my-trong-nhung-dot-khung-hoang-kinh-te', 'Chiêm nghiệm bản đồ sao của Mỹ trong những đợt khủng hoảng kinh tế vừa qua Suốt quý 1 TTTC có mức tăng trưởng đáng kể do kỳ vọng giảm lãi suất sớm vào tháng 5. Tuy nhiên bước sang quý 2 thì vĩ mô đã x…', 'Chiêm nghiệm bản đồ sao của Mỹ trong những đợt khủng hoảng kinh tế vừa qua

Suốt quý 1 TTTC có mức tăng trưởng đáng kể do kỳ vọng giảm lãi suất sớm vào tháng 5. Tuy nhiên bước sang quý 2 thì vĩ mô đã xấu hơn khi GDP giảm và CPI liên tục không như mong đợi. 

Trước đây chúng ta sợ tăng lãi suất, nhưng thời điểm hiện tại việc giữ lãi suất cao trong thời gian dài mới là điều đáng lo ngại. 

Dưới đây là bản đồ sao của 2 giai đoạn có vụ khủng hoảng tài chính lớn nhất và nghiêm trọng nhất là vụ vỡ bong bóng Dot-com và sụp đổ của Lehman Brother.

Trong vụ Dot-com năm 2000, góc chiếu xấu của sao Hỏa vào nhà 6 - ngôi nhà của nợ nần, call margin - kết hợp với La Hầu có góc chiếu vào sao Hỏa kích hoạt những hành động thiếu não. Sao Thủy lại đạng nghịch hành ở cung Bảo Bình gây ra nhịp bán tháo cho toàn thị trường. 

Còn năm 2008 chúng ta cũng nhìn thấy La Hầu tác động lên sao Hỏa và sao Thủy lại 1 lần nữa chiếu vào nhà 6. Năm đó tiếp tục có vụ phá sản của Lehman Brother gây chấn động toàn cầu. 

2024 thì hầu như các hành tinh đều không tạo ra góc chiếu tương tự, mặc dù La Hầu ở Song Ngư có gây ra chiến tranh, bất ổn liên quan tới thiên tai và dịch bệnh. Tuy nhiên sao Thủy sẽ sớm thoát khỏi thế bí khi đi vào cung Kim Ngưu.

Giai đoạn tháng 7 trở đi, lúc sao Thủy vào Kim Ngưu cũng sẽ trùng hợp với sao Kim và tạo góc chiếu vào nhà 2, lúc đó sẽ là động lực để thị trường bật tăng mạnh mẽ.', 'https://pbs.twimg.com/media/GMJ4HHNaoAABQZQ.jpg', 'Chu Kỳ Vũ Trụ & Thời Cuộc', '{"Thủy Tinh","Kim Tinh","Hỏa Tinh","La Hầu"}', 'published', 'Buddha.eth', 'Khảo luận Triết học, Chiêm tinh & Tâm thức', 2, 0, false, 'Chiêm nghiệm bản đồ sao của Mỹ trong những đợt khủng hoảng kinh tế vừa', 'Chiêm nghiệm bản đồ sao của Mỹ trong những đợt khủng hoảng kinh tế vừa qua Suốt quý 1 TTTC có mức tăng trưởng đáng kể do kỳ vọng giảm lãi suất sớm vào tháng 5. ', 'thủy tinh, kim tinh, hỏa tinh, la hầu', '2024-04-27T14:45:03+07:00', '2024-04-27T14:45:03+07:00')
